create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users on delete cascade, display_name text not null check(length(trim(display_name)) between 1 and 80));
create table public.games (id uuid primary key default gen_random_uuid(), host_id uuid not null references public.profiles, title text not null check(length(trim(title)) between 1 and 100), sport text not null, venue text not null, starts_at timestamptz not null, capacity integer not null check(capacity between 2 and 100), description text not null default '', status text not null default 'scheduled' check(status in ('scheduled','canceled')), created_at timestamptz not null default now());
create table public.game_participants (game_id uuid references public.games on delete cascade, user_id uuid references public.profiles on delete cascade, joined_at timestamptz not null default now(), primary key(game_id,user_id));
create table public.game_messages (id uuid primary key default gen_random_uuid(), game_id uuid not null references public.games on delete cascade, sender_id uuid not null references public.profiles, body text not null check(length(trim(body)) between 1 and 1000), created_at timestamptz not null default now());
alter table public.profiles enable row level security;
alter table public.games enable row level security;
alter table public.game_participants enable row level security;
alter table public.game_messages enable row level security;
create policy profiles_read on public.profiles for select to authenticated using (true);
create policy profiles_insert on public.profiles for insert to authenticated with check (id = auth.uid());
create policy profiles_update on public.profiles for update to authenticated using (id = auth.uid()) with check (id = auth.uid());
create policy games_read on public.games for select to authenticated using (true);
create policy roster_read on public.game_participants for select to authenticated using (true);
create policy messages_read on public.game_messages for select to authenticated using (exists(select 1 from public.game_participants p where p.game_id = game_messages.game_id and p.user_id = auth.uid()));
create policy messages_send on public.game_messages for insert to authenticated with check (sender_id = auth.uid() and exists(select 1 from public.game_participants p where p.game_id = game_messages.game_id and p.user_id = auth.uid()));
create function public.create_game(p_title text,p_sport text,p_venue text,p_starts_at timestamptz,p_capacity integer,p_description text) returns uuid language plpgsql security definer set search_path = public as $$ declare gid uuid; begin if auth.uid() is null or p_starts_at <= now() then raise exception 'Sign in and choose a future time'; end if; insert into games(host_id,title,sport,venue,starts_at,capacity,description) values(auth.uid(),p_title,p_sport,p_venue,p_starts_at,p_capacity,p_description) returning id into gid; insert into game_participants(game_id,user_id) values(gid,auth.uid()); return gid; end $$;
create function public.join_game(p_game_id uuid) returns void language plpgsql security definer set search_path = public as $$ declare g games%rowtype; begin select * into g from games where id=p_game_id for update; if auth.uid() is null or not found or g.status <> 'scheduled' or g.starts_at <= now() then raise exception 'Game unavailable'; end if; if exists(select 1 from game_participants where game_id=p_game_id and user_id=auth.uid()) then return; end if; if (select count(*) from game_participants where game_id=p_game_id) >= g.capacity then raise exception 'Game is full'; end if; insert into game_participants(game_id,user_id) values(p_game_id,auth.uid()); end $$;
create function public.leave_game(p_game_id uuid) returns void language plpgsql security definer set search_path = public as $$ declare g games%rowtype; begin select * into g from games where id=p_game_id for update; if auth.uid() is null or not found then raise exception 'Game unavailable'; end if; if g.host_id=auth.uid() then raise exception 'Hosts cannot leave their own game'; end if; delete from game_participants where game_id=p_game_id and user_id=auth.uid(); end $$;
revoke all on function public.create_game(text,text,text,timestamptz,integer,text), public.join_game(uuid), public.leave_game(uuid) from public, anon;
grant execute on function public.create_game(text,text,text,timestamptz,integer,text), public.join_game(uuid), public.leave_game(uuid) to authenticated;
